import assert from 'node:assert/strict';
import { readFileSync } from 'node:fs';
import { test } from 'node:test';

import { analyzePtx, buildLineLinks, demangle, summarize } from '../web/src/ptx-analyze.js';

// Real output of clang's NVPTX backend for tests/fixtures/k.cu (sm_100).
const CLANG_PTX = readFileSync(new URL('./fixtures/kernels_sm100.ptx', import.meta.url), 'utf8');

// nvcc-style text: typed registers, callseq scopes, inlined_at, a prototype.
const NVCC_PTX = `//
// Generated by NVIDIA NVVM Compiler
//
.version 8.5
.target sm_90
.address_size 64

.extern .func  (.param .b32 func_retval0) expf
(
	.param .b32 expf_param_0
)
;
.global .align 4 .b8 table[64];

.visible .entry _Z4copyPKfPfl(
	.param .u64 _Z4copyPKfPfl_param_0,
	.param .u64 _Z4copyPKfPfl_param_1,
	.param .u64 _Z4copyPKfPfl_param_2
)
{
	.reg .pred 	%p<3>;
	.reg .f32 	%f<4>;
	.reg .b32 	%r<6>;
	.reg .b64 	%rd<12>;
	.loc	1 4 0
	ld.param.u64 	%rd1, [_Z4copyPKfPfl_param_0];
	mov.u64 	%rd9, 0;
$L__BB0_1:
	.loc	1 6 5
	shl.b64 	%rd4, %rd9, 2;
	ld.global.f32 	%f1, [%rd4];
	.loc	2 10 3, function_name $L__info_string0, inlined_at 1 7 9
	div.s64 	%rd5, %rd9, %rd2;
	{ // callseq 0, 0
	.param .b32 param0;
	st.param.f32 	[param0+0], %f1;
	.param .b32 retval0;
	call.uni (retval0),
	expf,
	(
	param0
	);
	ld.param.f32 	%f2, [retval0+0];
	} // callseq 0
	st.global.f32 	[%rd4], %f2;
	add.s64 	%rd9, %rd9, 1;
	setp.lt.s64 	%p1, %rd9, %rd2;
	@%p1 bra 	$L__BB0_1;
	ret;
}
	.file	1 "/home/u/copy.cu"
	.file	2 "/usr/include/helper.h"
`;

const byName = (analysis, pretty) => analysis.functions.find((fn) => fn.pretty === pretty);

test('reads the module header and both entry functions from clang output', () => {
  const analysis = analyzePtx(CLANG_PTX);

  assert.equal(analysis.version, '8.6');
  assert.equal(analysis.target, 'sm_100');
  assert.match(analysis.generator, /LLVM NVPTX/);
  assert.deepEqual(analysis.functions.map((fn) => [fn.pretty, fn.kind, fn.params]),
    [['saxpy', 'entry', 4], ['rowsum', 'entry', 3]]);
});

test('counts the four double-precision ops caused by the 0.5 literal', () => {
  const saxpy = byName(analyzePtx(CLANG_PTX), 'saxpy');

  assert.equal(saxpy.fp64Ops, 4);
  assert.equal(saxpy.loops.length, 0);
  assert.deepEqual(saxpy.loads, { param: 4, global: 2 });
  assert.deepEqual(saxpy.stores, { global: 1 });
});

test('finds local memory, the barrier and the loops in rowsum', () => {
  const analysis = analyzePtx(CLANG_PTX);
  const rowsum = byName(analysis, 'rowsum');

  assert.equal(rowsum.localDepotBytes, 32);
  assert.equal(rowsum.barSync, 1);
  assert.ok(rowsum.loops.length >= 2, `loops: ${rowsum.loops.length}`);
  assert.ok(rowsum.stores.local > 0 && rowsum.loads.shared > 0);
  assert.ok(analysis.heat.length > 0);
  assert.ok(analysis.data.some((d) => d.space === 'shared' && d.bytes === 1024));
  assert.equal(rowsum.sharedBytes, 1024);
});

test('instruction mix adds up to the instruction count', () => {
  for (const fn of analyzePtx(CLANG_PTX).functions) {
    const total = Object.values(fn.mix).reduce((a, b) => a + b, 0);
    assert.equal(total, fn.instructions);
    assert.ok(fn.mix.memory > 0 && fn.mix.control > 0);
  }
});

test('lints point at PTX lines and carry the source line', () => {
  const analysis = analyzePtx(CLANG_PTX);
  const fp64 = analysis.lints.filter((lint) => lint.code === 'fp64');
  const lines = CLANG_PTX.split('\n');

  assert.equal(fp64.length, 4);
  for (const lint of fp64) {
    assert.match(lines[lint.line - 1], /f64/);
    assert.equal(lint.src.line, 3);
    assert.match(lint.src.file, /k\.cu$/);
  }
  assert.ok(analysis.lints.some((lint) => lint.code === 'local-mem' && lint.hot));
});

test('line links map source line 3 to its PTX and back, through inlined builtins', () => {
  const analysis = analyzePtx(CLANG_PTX);
  const { srcToPtx, ptxToSrc } = buildLineLinks(analysis, 'workspace/k.cu');
  const lines = CLANG_PTX.split('\n');

  assert.ok(srcToPtx.get(3).some((n) => /fma\.rn\.f64/.test(lines[n - 1])));
  const tid = lines.findIndex((l) => /%tid\.x/.test(l)) + 1;
  assert.equal(ptxToSrc.get(tid), 2); // threadIdx is inlined from a header; it maps to the call site
  assert.equal(buildLineLinks(analysis, 'other.cu').srcToPtx.size, 0);
});

test('nvcc style: typed registers, prototype skipped, callseq scope stays inside the function', () => {
  const analysis = analyzePtx(NVCC_PTX);
  const [copy] = analysis.functions;

  assert.equal(analysis.functions.length, 1);
  assert.equal(copy.pretty, 'copy');
  assert.deepEqual(copy.regs, { pred: 3, f32: 4, b32: 6, b64: 12 });
  assert.deepEqual(copy.calls, ['expf']);
  assert.equal(copy.loops.length, 1);
  assert.equal(copy.instructions, 13);
  assert.deepEqual(analysis.data, [{ space: 'global', name: 'table', bytes: 64, line: 13 }]);
});

test('nvcc style: hot 64-bit division and the call are reported; inlined_at wins for the source line', () => {
  const analysis = analyzePtx(NVCC_PTX);
  const div = analysis.lints.find((lint) => lint.code === 'int-div');
  const call = analysis.lints.find((lint) => lint.code === 'call');

  assert.equal(div.severity, 'warn');
  assert.equal(div.hot, true);
  assert.deepEqual(div.src, { file: '/home/u/copy.cu', line: 7 });
  assert.match(call.message, /expf/);
});

test('summary for the model joins ptxas registers by symbol', () => {
  const analysis = analyzePtx(CLANG_PTX);
  const summary = summarize(analysis, 'k.cu', [
    { function: '_Z5saxpyfPKfPfi', registers: 8, spill_stores: 0, spill_loads: 0 }]);

  assert.equal(summary.functions[0].registers, 8);
  assert.equal(summary.functions[1].registers, null);
  assert.equal(summary.lints.find((l) => l.code === 'fp64').source_line, 3);
  assert.ok(!JSON.stringify(summary).includes('ld.global'), 'no PTX text in the summary');
});

test('demangle handles plain, nested and unmangled names', () => {
  assert.equal(demangle('_Z6rowsumPKfPfi'), 'rowsum');
  assert.equal(demangle('_ZN3foo3barEv'), 'foo::bar');
  assert.equal(demangle('softmax_kernel'), 'softmax_kernel');
});

test('empty and broken input do not throw', () => {
  assert.deepEqual(analyzePtx('').functions, []);
  assert.deepEqual(analyzePtx('.entry broken(\n{\n add.s32 %r1, %r1, 1;\n').functions, []);
});
